<template><section class="patient-page"><header class="patient-page-header"><div><p class="eyebrow">CONFIGURATION</p><h1>Settings</h1><p class="page-subtitle">ช่องทางการชำระเงินที่เปิดใช้งาน</p></div><button @click="load">รีเฟรช</button></header><p v-if="errorMessage" class="error">{{ errorMessage }}</p><div v-if="loading" class="state-card">กำลังโหลด...</div><div v-else-if="!methods.length" class="state-card">ยังไม่มีช่องทางการชำระเงิน</div><div v-else class="patient-results"><article v-for="method in methods" :key="method.id" class="patient-result-card"><div><span class="patient-hn">{{ method.code }}</span><h2>{{ method.name }}</h2><p>ช่องทางชำระเงินที่ใช้งานอยู่</p></div><span class="status-badge">Active</span></article></div></section></template>
<script setup lang="ts">import { onMounted, ref } from 'vue'; import { listPaymentMethods, type PaymentMethod } from '@/api/payments'; const methods=ref<PaymentMethod[]>([]); const loading=ref(false); const errorMessage=ref(''); async function load(){loading.value=true;try{methods.value=await listPaymentMethods()}catch(e){errorMessage.value=e instanceof Error?e.message:'เกิดข้อผิดพลาด'}finally{loading.value=false}} onMounted(load)</script>
